package com.whaa.shop.product.domain;
import com.baomidou.mybatisplus.annotation.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@TableName("product") public class Product { @TableId(type=IdType.AUTO) private Long id; private Long categoryId; private String name; private String subtitle; private String mainImage; private String detailHtml; private BigDecimal minPrice; private Long sales; private Boolean published; private LocalDateTime createdAt;
 public Long getId(){return id;} public void setId(Long v){id=v;} public Long getCategoryId(){return categoryId;} public void setCategoryId(Long v){categoryId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getSubtitle(){return subtitle;} public void setSubtitle(String v){subtitle=v;} public String getMainImage(){return mainImage;} public void setMainImage(String v){mainImage=v;} public String getDetailHtml(){return detailHtml;} public void setDetailHtml(String v){detailHtml=v;} public BigDecimal getMinPrice(){return minPrice;} public void setMinPrice(BigDecimal v){minPrice=v;} public Long getSales(){return sales;} public void setSales(Long v){sales=v;} public Boolean getPublished(){return published;} public void setPublished(Boolean v){published=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}}

